local RunService = game:GetService("RunService")
local Matter = require(game.ReplicatedStorage.Packages.Matter)
local Plasma = require(game.ReplicatedStorage.Packages.Plasma)
local HotReloader = require(game.ReplicatedStorage.Packages.rewire).HotReloader
local HookWidgets = require(script.Parent.hookWidgets)

local function start(
	containers,
	components,
	services: IServiceProvider,
	playerScopeProvider: (useridOrPlayer: number | Player) -> IServiceScope
)
	local world = Matter.World.new()

	local debugger = Matter.Debugger.new(Plasma)
	debugger.getMatter = function(debugger)
		return Matter
	end
	debugger.getComponents = function(debugger)
		return components
	end
	debugger.getPlasma = function(debugger)
		return Plasma
	end
	debugger.getWorld = function(debugger)
		return world
	end

	local originGetWidgets = debugger.getWidgets

	debugger.getWidgets = function(debugger)
		local widgets = originGetWidgets(debugger)
		local widgets2 = HookWidgets(debugger)
		for k, v in widgets2 do
			widgets[k] = v
		end
		return widgets
	end

	local loop = Matter.Loop.new(world, debugger, services, playerScopeProvider)

	loop:setWorlds({ World = world })

	-- Set up hot reloading

	local hotReloader = HotReloader.new()

	local firstRunSystems = {}
	local systemsByModule = {}

	local function loadModule(module, context)
		local originalModule = context.originalModule

		local ok, system = pcall(require, module)

		if not ok then
			warn("Error when hot-reloading system", module.name, system)
			return
		end

		if firstRunSystems then
			table.insert(firstRunSystems, system)
		elseif systemsByModule[originalModule] then
			loop:replaceSystem(systemsByModule[originalModule], system)
			debugger:replaceSystem(systemsByModule[originalModule], system)
		else
			loop:scheduleSystem(system)
		end

		systemsByModule[originalModule] = system
	end

	local function unloadModule(_, context)
		if context.isReloading then
			return
		end

		local originalModule = context.originalModule
		if systemsByModule[originalModule] then
			loop:evictSystem(systemsByModule[originalModule])
			systemsByModule[originalModule] = nil
		end
	end

	for _, container in containers do
		hotReloader:scan(container, loadModule, unloadModule)
	end

	loop:scheduleSystems(firstRunSystems)
	firstRunSystems = nil

	debugger:autoInitialize(loop)

	-- Begin running our systems

	loop:begin({
		default = RunService.Heartbeat,
		Stepped = RunService.Stepped,
	})

	return debugger
end

return start
